package com.audiobookdownloader;
import android.app.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.text.SimpleDateFormat;import java.util.*;import java.util.concurrent.*;
/** Native transfer screen remains usable independently of the Compose player. */
public final class CollectionTransferActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private CollectionTransferStore store;private TextView status;private Button open,export,apply,undo;private String pending;private boolean working;
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 private TextView text(LinearLayout root,String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextColor(Color.WHITE);t.setTextSize(size);t.setPadding(0,dp(8),0,dp(8));root.addView(t);return t;}
 private Button button(LinearLayout root,String value,Runnable action){Button b=new Button(this);b.setText(value);b.setAllCaps(false);b.setTextColor(0xfff2d2a4);GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff253144,0xff121925});bg.setCornerRadius(dp(18));bg.setStroke(dp(1),0xffbb925d);b.setBackground(bg);b.setPadding(dp(12),dp(10),dp(12),dp(10));b.setMinHeight(dp(54));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(10);root.addView(b,p);b.setOnClickListener(v->action.run());return b;}
 @Override public void onCreate(Bundle b){super.onCreate(b);store=new CollectionTransferStore(this);getWindow().setStatusBarColor(0xff101725);getWindow().setNavigationBarColor(0xff101725);ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(0xff101725);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(22),dp(20),dp(22),dp(28));root.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(dp(22),dp(20)+insets.getSystemWindowInsetTop(),dp(22),dp(28)+insets.getSystemWindowInsetBottom());return insets;});scroll.addView(root);setContentView(scroll);
  text(root,"Перенос коллекций",25).setTypeface(null,Typeface.BOLD);text(root,"Добавьте коллекции из сохранённого JSON/XML. Перенос дополняет текущие коллекции. Старая версия и аудиофайлы не изменяются.",15);
  status=text(root,"Выберите сохранённый JSON/XML-файл коллекций. Перед добавлением приложение покажет результат проверки; текущие полки и книги сохраняются.",14);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);
  text(root,"Прямое чтение другого приложения и перенос с его экранов удалены. Если копии коллекций нет, книги можно добавить в полки вручную. Аудиофайлы подключаются отдельно через выбор папки библиотеки.",14);
  open=button(root,"Импортировать JSON/XML",()->{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/json","text/plain","text/xml","application/xml","application/octet-stream"});try{startActivityForResult(intent,51);}catch(Exception e){status.setText("Не удалось открыть выбор файла");}});
  apply=button(root,"Добавить найденные коллекции",this::apply);apply.setEnabled(false);
  export=button(root,"Сохранить копию коллекций",()->{String name="Audiobook-collections-"+new SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(new Date())+".json";try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json").putExtra(Intent.EXTRA_TITLE,name),52);}catch(Exception e){status.setText("Не удалось открыть сохранение файла");}});
  undo=button(root,"Отменить последний импорт",()->run(()->{store.undo();return "Коллекции восстановлены из копии перед импортом";}));undo.setEnabled(store.canUndo());text(root,"Копия перед последним импортом сохраняется внутри приложения. Отмена доступна, пока коллекции не менялись после переноса. Повторный импорт не создаёт дубликатов.",13);
 }
 private interface Task{String work()throws Exception;}
 private void busy(boolean value){working=value;open.setEnabled(!value);export.setEnabled(!value);apply.setEnabled(!value&&pending!=null);undo.setEnabled(!value&&store.canUndo());}
 private void run(Task task){busy(true);status.setText("Подождите…");worker.submit(()->{String result;try{result=task.work();}catch(Exception e){result=e instanceof IllegalArgumentException||e instanceof IOException?e.getMessage():"Не удалось обработать коллекции. Проверьте файл и повторите попытку";}String message=result;runOnUiThread(()->{if(isDestroyed()||isFinishing())return;busy(false);status.setText(message);});});}
 private String stage(String document)throws Exception{String normalized=CollectionTransferRules.export(document);var result=store.preview(normalized);pending=normalized;return "Найдено коллекций: "+CollectionTransferRules.parse(normalized).length()+". Новых коллекций: "+result.addedShelves+", книг: "+result.addedBooks+". Нажмите «Добавить найденные коллекции» для переноса.";}
 private void apply(){if(pending==null)return;String data=pending;run(()->{var result=store.apply(data);pending=null;return "Добавлено коллекций: "+result.addedShelves+", книг: "+result.addedBooks+". Дополнено ссылок/обложек: "+result.filledReferences+".";});}
 static String read(InputStream in)throws Exception{try(InputStream input=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=input.read(b))!=-1){if(out.size()+n>CollectionTransferRules.MAX_BYTES)throw new IllegalArgumentException("Файл коллекций слишком большой");out.write(b,0,n);}return new String(out.toByteArray(),StandardCharsets.UTF_8);}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(request==51){pending=null;run(()->stage(read(getContentResolver().openInputStream(uri))));}else if(request==52)run(()->{String json=CollectionTransferRules.export(store.current());try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Не удалось открыть файл");out.write(json.getBytes(StandardCharsets.UTF_8));}return "Копия коллекций сохранена";});}
 @Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
